# This formula is generated by goreleaser on release once
# HOMEBREW_TAP_GITHUB_TOKEN is configured. It was written by hand for 1.0.0
# so `brew install` worked from day one; later versions overwrite it.
class Birdy < Formula
  desc "Multi-account X/Twitter CLI with account rotation, in one Go binary"
  homepage "https://github.com/guzus/birdy"
  version "1.0.0"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/guzus/birdy/releases/download/v1.0.0/birdy_darwin_arm64.tar.gz"
      sha256 "3ea854d555eafe0f669eba8dc3f54be1ff14bcce07f54c6f18a5973767b6600c"
    end
    on_intel do
      url "https://github.com/guzus/birdy/releases/download/v1.0.0/birdy_darwin_amd64.tar.gz"
      sha256 "ada292b98ede6f0a097990b3c297b2f86061317565627cde891ea9916ff31051"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/guzus/birdy/releases/download/v1.0.0/birdy_linux_arm64.tar.gz"
      sha256 "7499319d309a1a4b60b3a3685744063f698e3668d2dd96d9bd3e343e87aaf161"
    end
    on_intel do
      url "https://github.com/guzus/birdy/releases/download/v1.0.0/birdy_linux_amd64.tar.gz"
      sha256 "a29676d7b4f7a9bd8268e21cb5b3f774c7a7fcf1a2969548932f8fc66353c97a"
    end
  end

  def install
    bin.install "birdy"
  end

  test do
    assert_match "birdy", shell_output("#{bin}/birdy version")
  end
end
